import React,{useEffect,useMemo,useState,useRef} from 'react';
import {View,Text,StyleSheet,Pressable,ScrollView,TextInput,Modal,Switch,Image,Share,Platform,ActivityIndicator,KeyboardAvoidingView,Alert,RefreshControl} from 'react-native';
import {SafeAreaProvider,SafeAreaView} from 'react-native-safe-area-context';
import {Ionicons} from '@expo/vector-icons';
