import QRCode from 'react-native-qrcode-svg';
import {categories,findMatches,contactOrSensitive,canonical,preferenceOf,preferenceNames,preferenceQuestions,normalizeInstagram,normalizeLinkedIn,positiveInterests,type Preference,type Interest,type Profile,type Match} from '../shared/matching';
import {rankInterests,suggestGroups} from '../shared/grouping';
